import java.sql.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Connection conn = DriverManager.getConnection("jdbc:sqlite:school.db");
        Statement stmt = conn.createStatement();
        stmt.executeUpdate("""CREATE TABLE IF NOT EXISTS students (
            id INTEGER PRIMARY KEY,
            name TEXT NOT NULL,
            age INTEGER,
            marks REAL
        )""");
        conn.close();
    }
}

stmt.executeUpdate("""CREATE TABLE courses (
    id INTEGER PRIMARY KEY,
    title TEXT,
    student_id INTEGER,
    FOREIGN KEY (student_id) REFERENCES students(id)
)""");

PreparedStatement ps = conn.prepareStatement(
    "INSERT INTO students (name, age, marks) VALUES (?, ?, ?)");
ps.setString(1, "Priya");
ps.setInt(2, 20);
ps.setDouble(3, 91.5);
ps.executeUpdate();

// UPDATE
conn.prepareStatement("UPDATE students SET marks=? WHERE name=?")
    .executeUpdate();

PreparedStatement ps = conn.prepareStatement(
    "SELECT name, marks FROM students WHERE marks > ?");
ps.setDouble(1, 80);
ResultSet rs = ps.executeQuery();
while (rs.next()) {
    System.out.println(rs.getString("name") + " " + rs.getDouble("marks"));
}

ResultSet rs = stmt.executeQuery(
    "SELECT name, marks FROM students ORDER BY marks DESC");
while (rs.next()) {
    System.out.println(rs.getString("name"));
}

rs = stmt.executeQuery(
    "SELECT course_id, AVG(marks), COUNT(*) FROM enrollments GROUP BY course_id");

ResultSet rs = stmt.executeQuery("""
    SELECT students.name, courses.title
    FROM students
    JOIN enrollments ON students.id = enrollments.student_id
    JOIN courses ON courses.id = enrollments.course_id""");
while (rs.next()) {
    System.out.println(rs.getString(1) + " -> " + rs.getString(2));
}

ResultSet rs = stmt.executeQuery(
    "SELECT COUNT(*), AVG(marks), MIN(marks), MAX(marks) FROM students");
rs.next();
System.out.println("Students: " + rs.getInt(1)
    + ", Avg: " + rs.getDouble(2));

conn.setAutoCommit(false);
try {
    stmt.executeUpdate("CREATE INDEX idx_name ON students(name)");
    ps.executeUpdate();   // insert
    conn.commit();
} catch (SQLException e) {
    conn.rollback();
} finally {
    conn.setAutoCommit(true);
}
